import React, { FC, useEffect, useState } from 'react';
import '../App.css';
import { SnackbarProvider, useSnackbar } from 'notistack';
import CustomTheme from '../CustomTheme';
import {
    IconButton, Box, Alert, Card, CardContent, Typography,
    CircularProgress, Table, TableBody, TableCell, TableHead, TableRow
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import { fetchScannedDevices } from '../api/DeviceScannerService';

const Devices: FC = () => {
    const { enqueueSnackbar } = useSnackbar();
    const [devices, setDevices] = useState<any | null>(null);
    const [loading, setLoading] = useState<boolean>(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const loadDevices = async () => {
            try {
                const data = await fetchScannedDevices();
                setDevices(data);
            } catch (err) {
                setError('Failed to load scanned devices.');
                enqueueSnackbar('Failed to load scanned devices.', { variant: 'error' });
            } finally {
                setLoading(false);
            }
        };
        loadDevices();
    }, []);

    if (loading) {
        return (
            <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
                <CircularProgress />
            </Box>
        );
    }

    if (error) {
        return (
            <Typography variant="h6" color="error" align="center">
                {error}
            </Typography>
        );
    }

    if (!devices || Object.keys(devices).length === 0) {
        return (
            <Typography variant="h6" align="center">
                No devices found.
            </Typography>
        );
    }

    return (
        <CustomTheme>
            <SnackbarProvider maxSnack={3} anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}>
                <Card sx={{ margin: 2, padding: 2 }}>
                    <CardContent>
                        <Typography variant="h5" gutterBottom>
                            Detected Devices
                        </Typography>

                        <Table>
                            <TableHead>
                                <TableRow>
                                    <TableCell>Device Type</TableCell>
                                    <TableCell>Pin/Address</TableCell>
                                    <TableCell>Value</TableCell>
                                    <TableCell>Status</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {/* Handle I2C Devices */}
                                {devices.i2cDevices && devices.i2cDevices.length > 0 ? (
                                    devices.i2cDevices.map((device: any, index: number) => (
                                        <TableRow key={`i2c-${index}`}>
                                            <TableCell>I2C</TableCell>
                                            <TableCell>{device.address}</TableCell>
                                            <TableCell>--</TableCell>
                                            <TableCell>✔️</TableCell>
                                        </TableRow>
                                    ))
                                ) : (
                                    <TableRow>
                                        <TableCell colSpan={4} align="center">No I2C Devices Found</TableCell>
                                    </TableRow>
                                )}

                                {/* Handle Analog Pins */}
                                {devices.analogPins && devices.analogPins.length > 0 ? (
                                    devices.analogPins.map((device: any, index: number) => (
                                        <TableRow key={`analog-${index}`}>
                                            <TableCell>Analog</TableCell>
                                            <TableCell>{device.pin}</TableCell>
                                            <TableCell>{device.value}</TableCell>
                                            <TableCell>✔️</TableCell>
                                        </TableRow>
                                    ))
                                ) : (
                                    <TableRow>
                                        <TableCell colSpan={4} align="center">No Analog Devices Found</TableCell>
                                    </TableRow>
                                )}

                                {/* Handle Digital Pins */}
                                {devices.digitalPins && devices.digitalPins.length > 0 ? (
                                    devices.digitalPins.map((device: any, index: number) => (
                                        <TableRow key={`digital-${index}`}>
                                            <TableCell>Digital</TableCell>
                                            <TableCell>{device.pin}</TableCell>
                                            <TableCell>{device.value}</TableCell>
                                            <TableCell>✔️</TableCell>
                                        </TableRow>
                                    ))
                                ) : (
                                    <TableRow>
                                        <TableCell colSpan={4} align="center">No Digital Devices Found</TableCell>
                                    </TableRow>
                                )}

                                {/* Handle UART Devices */}
                                {devices.uartDevices && devices.uartDevices.length > 0 ? (
                                    devices.uartDevices.map((device: any, index: number) => (
                                        <TableRow key={`uart-${index}`}>
                                            <TableCell>UART</TableCell>
                                            <TableCell>{device.port}</TableCell>
                                            <TableCell>{device.value || '--'}</TableCell>
                                            <TableCell>✔️</TableCell>
                                        </TableRow>
                                    ))
                                ) : (
                                    <TableRow>
                                        <TableCell colSpan={4} align="center">No UART Devices Found</TableCell>
                                    </TableRow>
                                )}

                                {/* Handle SPI Devices */}
                                {devices.spiDevices && devices.spiDevices.length > 0 ? (
                                    devices.spiDevices.map((device: any, index: number) => (
                                        <TableRow key={`spi-${index}`}>
                                            <TableCell>SPI</TableCell>
                                            <TableCell>{device.bus}</TableCell>
                                            <TableCell>{device.value || '--'}</TableCell>
                                            <TableCell>✔️</TableCell>
                                        </TableRow>
                                    ))
                                ) : (
                                    <TableRow>
                                        <TableCell colSpan={4} align="center">No SPI Devices Found</TableCell>
                                    </TableRow>
                                )}
                            </TableBody>
                        </Table>
                    </CardContent>
                </Card>
            </SnackbarProvider>
        </CustomTheme>
    );
};

export default Devices;